// ===== EDIT YOUR SETTINGS HERE =====
const GOOGLE_SHEET_ID = 'your-google-sheet-id';
const SHEET_NAME = 'Leads';

const email = $input.first().json;

const fromValue = email.from?.value?.[0] || email.from || {};
const senderEmail =
  typeof fromValue === 'string'
    ? fromValue.match(/[\w.+-]+@[\w.-]+\.\w+/)?.[0] || fromValue
    : fromValue.address || '';
const senderName =
  typeof fromValue === 'string'
    ? fromValue.replace(senderEmail, '').replace(/[<>"]/g, '').trim()
    : fromValue.name || '';

const subject = email.subject || '';
const body = email.textPlain || email.text || email.snippet || '';
const messageId = email.id || email.messageId || '';
const receivedAt = email.date || new Date().toISOString();

const phoneMatch = body.match(/(\+?\d[\d\s\-().]{7,}\d)/);
const phone = phoneMatch ? phoneMatch[1].trim() : '';

return [
  {
    json: {
      googleSheetId: GOOGLE_SHEET_ID,
      sheetName: SHEET_NAME,
      email: senderEmail,
      name: senderName,
      subject,
      body: body.slice(0, 500),
      phone,
      messageId,
      receivedAt,
    },
  },
];

const lead = $('Extract Lead Details').first().json;
const rows = $input.all();

const isDuplicate = rows.some((item) => {
  const row = item.json;
  const existingEmail = row.Email || row.email || row['Email Address'] || '';
  const existingMessageId = row['Message ID'] || row.messageId || row.MessageId || '';

  if (existingMessageId && lead.messageId && existingMessageId === lead.messageId) {
    return true;
  }

  return (
    existingEmail &&
    lead.email &&
    String(existingEmail).toLowerCase() === String(lead.email).toLowerCase()
  );
});

return [
  {
    json: {
      ...lead,
      isDuplicate,
    },
  },
];
